"""Build a self-contained, file://-friendly audition page from measured files and sidecars."""
from pathlib import Path
import json
import html
from datetime import datetime, timezone
from report_format import decorate

BASE = Path('audio/audition')


def read(name):
    return json.loads((BASE / name).read_text(encoding='utf-8'))


def main():
    plan, acceptance = read('plan.json'), read('acceptance.json')
    before = read('credits-before.json')
    after = read('credits-final.json') if (BASE / 'credits-final.json').exists() else read('credits-after.json')
    ledger = [json.loads(s) for s in Path('tools/audio/ledger.jsonl').read_text().splitlines() if s]
    latest = {r['id']: r for r in ledger if r['session'] == plan['session']}
    rows = []
    for sample in plan['samples']:
        sidecar = BASE / 'raw' / (sample['id'] + '.mp3.json')
        rows.append({**sample, 'provenance': json.loads(sidecar.read_text()) if sidecar.exists() else None,
                     'acceptance': next(r for r in acceptance['samples'] if r['id'] == sample['id'])})
    summary = {
        'at': read('spend-report.json')['at'] if (BASE / 'spend-report.json').exists() else datetime.now(timezone.utc).isoformat(), 'session': plan['session'], 'cap': plan['cap'], 'reserve': plan['reserve'],
        'before': before, 'after': after, 'accountDecrease': before['remaining'] - after['remaining'],
        'budgetUsed': sum(r['budgetCharge'] for r in latest.values()),
        'providerReportedCredits': sum(r.get('providerCredits') or 0 for r in latest.values()),
        'providerReportedTakes': sum(r.get('providerCredits') is not None for r in latest.values()),
        'unconfirmedTakes': [r['out'] for r in latest.values() if r['status'] == 'complete' and r.get('providerCredits') is None],
        'rejectedReservedCredits': sum(r['budgetCharge'] for r in latest.values() if r['status'] == 'abandoned-reserved'),
        'completedTakes': sum(r['status'] == 'complete' for r in latest.values()),
        'rawPass': sum(r.get('raw', {}).get('status') == 'pass' for r in acceptance['samples']),
        'matchedPass': sum(r.get('matched', {}).get('status') == 'pass' for r in acceptance['samples']),
        'notMeasured': 'Owner preference, in-game mix/masking/latency, Stick playback/memory, speech fidelity and identity, measured musical grid, long-race fatigue.',
        'billingCaveat': 'Account balances are shared and billing can lag. Per-request headers are authoritative where present; music billing is unconfirmed, not zero. Conservative reservations remain charged against the session cap.'
    }
    (BASE / 'spend-report.json').write_text(json.dumps(summary, indent=2) + '\n', encoding='utf-8', newline='\n')
    data = json.dumps({'plan': plan, 'summary': summary, 'rows': rows}, ensure_ascii=False).replace('<', '\\u003c')
    document = decorate(TEMPLATE.replace('__DATA__', data), 'deathride.audio.x2', 'X2 four philosophies', '../', 'deathride-audio-notes')
    (BASE / 'index.html').write_text(document, encoding='utf-8', newline='\n')
    print(json.dumps(summary, indent=2))


